var LZString = (function () {
    var f = String.fromCharCode;

    function _compress(uncompressed, bitsPerChar, getCharFromInt) {
        if (uncompressed == null) return '';
        var i, value, context_dictionary = new Map(), context_dictionaryToCreate = new Set(), context_c = '', context_wc = '', context_w = '',
            context_enlargeIn = 2, context_dictSize = 3, context_numBits = 2, context_data = [], context_data_val = 0, context_data_position = 0, ii;

        function writeBit(bit) {
            context_data_val = (context_data_val << 1) | bit;
            if (context_data_position == bitsPerChar - 1) {
                context_data_position = 0;
                context_data.push(getCharFromInt(context_data_val));
                context_data_val = 0;
            } else context_data_position++;
        }
        function writeBits(numBits, val) {
            for (var k = 0; k < numBits; k++) { writeBit(val & 1); val = val >> 1; }
        }
        function emitW() {
            if (context_dictionaryToCreate.has(context_w)) {
                var code = context_w.charCodeAt(0);
                if (code < 256) { writeBits(context_numBits, 0); writeBits(8, code); }
                else { writeBits(context_numBits, 1); writeBits(16, code); }
                context_enlargeIn--;
                if (context_enlargeIn == 0) { context_enlargeIn = Math.pow(2, context_numBits); context_numBits++; }
                context_dictionaryToCreate.delete(context_w);
            } else {
                writeBits(context_numBits, context_dictionary.get(context_w));
            }
            context_enlargeIn--;
            if (context_enlargeIn == 0) { context_enlargeIn = Math.pow(2, context_numBits); context_numBits++; }
        }

        for (ii = 0; ii < uncompressed.length; ii += 1) {
            context_c = uncompressed.charAt(ii);
            if (!context_dictionary.has(context_c)) {
                context_dictionary.set(context_c, context_dictSize++);
                context_dictionaryToCreate.add(context_c);
            }
            context_wc = context_w + context_c;
            if (context_dictionary.has(context_wc)) {
                context_w = context_wc;
            } else {
                emitW();
                context_dictionary.set(context_wc, context_dictSize++);
                context_w = String(context_c);
            }
        }
        if (context_w !== '') emitW();
        writeBits(context_numBits, 2); // koniec strumienia
        while (true) {
            context_data_val = (context_data_val << 1);
            if (context_data_position == bitsPerChar - 1) { context_data.push(getCharFromInt(context_data_val)); break; }
            else context_data_position++;
        }
        return context_data.join('');
    }

    function _decompress(length, resetValue, getNextValue) {
        var dictionary = [], enlargeIn = 4, dictSize = 4, numBits = 3, entry = '', result = [], i, w, c,
            data = { val: getNextValue(0), position: resetValue, index: 1 };

        function readBits(n) {
            var bits = 0, maxpower = Math.pow(2, n), power = 1, resb;
            while (power != maxpower) {
                resb = data.val & data.position;
                data.position >>= 1;
                if (data.position == 0) { data.position = resetValue; data.val = getNextValue(data.index++); }
                bits |= (resb > 0 ? 1 : 0) * power;
                power <<= 1;
            }
            return bits;
        }

        for (i = 0; i < 3; i += 1) dictionary[i] = i;
        switch (readBits(2)) {
            case 0: c = f(readBits(8)); break;
            case 1: c = f(readBits(16)); break;
            case 2: return '';
        }
        dictionary[3] = c;
        w = c;
        result.push(c);
        while (true) {
            if (data.index > length) return '';
            c = readBits(numBits);
            switch (c) {
                case 0: dictionary[dictSize++] = f(readBits(8)); c = dictSize - 1; enlargeIn--; break;
                case 1: dictionary[dictSize++] = f(readBits(16)); c = dictSize - 1; enlargeIn--; break;
                case 2: return result.join('');
            }
            if (enlargeIn == 0) { enlargeIn = Math.pow(2, numBits); numBits++; }
            if (dictionary[c]) entry = dictionary[c];
            else if (c === dictSize) entry = w + w.charAt(0);
            else return null;
            result.push(entry);
            dictionary[dictSize++] = w + entry.charAt(0);
            enlargeIn--;
            w = entry;
            if (enlargeIn == 0) { enlargeIn = Math.pow(2, numBits); numBits++; }
        }
    }

    return {
        compressToUTF16: function (input) {
            if (input == null) return '';
            return _compress(input, 15, function (a) { return f(a + 32); }) + ' ';
        },
        decompressFromUTF16: function (compressed) {
            if (compressed == null) return '';
            if (compressed == '') return null;
            return _decompress(compressed.length, 16384, function (index) { return compressed.charCodeAt(index) - 32; });
        }
    };
})();
if (typeof module !== 'undefined' && module != null) module.exports = LZString;
